/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,14],[14,38],[38,58],[58,78]]);
  var cin = lin([[0,0],[10,1]]);
  v.pts = 'scan ' + Math.round(cin * 100) + '%';
  var gw = lin([[16,0],[30,1]]), go = lin([[40,0],[50,1]]), gc = lin([[60,0],[70,1]]);
  v.fl = lin([[15,0],[19,1]]) * out;
  for (var i = 0; i < 5; i++) { var f = lin([[18 + i * 2.4, 0],[21 + i * 2.4, 1]]); v['w'+i] = 'opacity: ' + (f * out).toFixed(3) + ';'; }
  v.op = go * out;
  v.ce = 'opacity: ' + (gc * out).toFixed(3) + '; transform: translateY(' + (-16 * (1 - gc)).toFixed(1) + 'px);';
  v.c_plane = cin * (1 - 0.9 * gw) * out; v.c_open = cin * (1 - 0.9 * go) * out; v.c_ceil = cin * (1 - 0.9 * gc) * out;
  v.dw = (p >= 31 && p < 97) ? out : 0; v.dd = (p >= 51 && p < 97) ? out : 0; v.dc = (p >= 71 && p < 97) ? out : 0;
  v.fin = (p >= 74 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
